class ExerciseCatalogData extends DataClass
    implements Insertable<ExerciseCatalogData> {
  final String? syncUuid;
  final DateTime? updatedAt;
  final DateTime? syncedAt;
  final DateTime? deletedAt;
  final int id;

  /// Stable identity (v17), kebab-case, unique across seeded rows.
  ///
  /// [name] is display text and will change as the catalog is corrected; the
  /// importer matches on this instead so a rename updates the row in place
  /// rather than inserting a duplicate and orphaning every logged set that
  /// referenced the old row. Null on custom and pre-v17 rows.
  final String? slug;
  final String name;
  final String primaryMuscle;
  final String equipment;
  final String mechanics;
  final String force;
  final String plane;
  final int defaultRestSeconds;
  final bool isCustom;

  /// Denormalized alias blob for quick search; canonical aliases live in
  /// [ExerciseAliases]. Display always uses [name].
  final String? aka;
  final String category;
  final String? movementPattern;

  /// Original granular pattern text from the source dataset (fidelity).
  final String? movementPatternRaw;
  final String modality;

  /// CNS fatigue cost, 1–10. Drives recovery + max-effort logic.
  final int cnsScore;

  /// Systemic recovery demand, 1–5.
  final int recoveryImpact;
  final String loggingMetric;

  /// Enables the "+ added weight" field & bodyweight-base calculations.
  final bool supportsWeightedBodyweight;

  /// JSON list of attachment labels, e.g. ["rope","v-bar"]. Null = none.
  final String? attachments;

  /// False = attributes were machine-derived and not yet human-reviewed.
  final bool isReviewed;

  /// Movement-family key grouping equipment variants of the same movement
  /// (e.g. "Incline Barbell Bench" + "Incline Dumbbell Press" share one
  /// family). Drives the collapsed picker. Computed at import time; null on
  /// legacy/custom rows until backfilled.
  final String? movementFamily;

  /// Authored movement this exercise belongs to (`assets/data/movements.json`),
  /// e.g. every equipment variant of a curl shares `curl-isolation`. Supersedes
  /// the derived [movementFamily] for picker grouping; null means the exercise
  /// stands alone.
  final String? movementSlug;

  /// JSON array of modalities this exercise can plausibly be performed with,
  /// taken from its movement. Null means no swap is offered.
  ///
  /// Replaces the previous hardcoded free-weight family, which offered a Smith
  /// Machine option on a selectorized hamstring curl.
  final String? allowedEquipment;

  /// JSON array of concrete equipment keys required to perform the exercise.
  /// Unlike [allowedEquipment], every listed key must be available at the
  /// selected gym. An empty/null list means the legacy modality is used.
  final String? requiredEquipmentKeys;

  /// suitable | advanced_manual | unsuitable. Smart programming only uses
  /// `suitable`; guided/manual flows may expose the guarded advanced option.
  final String? maxEffortEligibility;
  final String? programmingDifficulty;
  final String? programmingCommonness;

  /// JSON array of canonical programme styles the exercise is curated for,
  /// such as ["weightlifting", "basic"] or ["calisthenics"].  An empty
  /// list means the row is manual-only until it is explicitly curated.
  final String? allowedTrainingStyles;

  /// automatic | technical_review | manual_only.  This is independent of
  /// difficulty: an advanced athlete may opt into a technical-review lift,
  /// while `manual_only` movements are never selected by the generator.
  final String? technicalEligibility;

  /// JSON array of canonical disciplines: weights, calisthenics, crossfit,
  /// olympic, gpp.
  final String? disciplines;

  /// JSON array of exercise or movement slugs required as foundational
  /// prerequisites before this movement is eligible for auto-programming.
  final String? prerequisiteSlugs;

  /// Progression ladder identifier (e.g. 'vertical_pull', 'horizontal_push',
  /// 'dips', 'squat', 'hinge').
  final String? scalingGroup;

  /// 1-indexed difficulty rank within the [scalingGroup] (1 = easiest regression).
  final int? scalingOrder;

  /// Primary competition anchor identity (e.g. 'squat', 'bench', 'deadlift',
  /// 'overhead_press').
  final String? competitionAnchor;

  /// JSON array of sticking-point or specialization tags (e.g.
  /// '["squat-bottom", "squat-mid"]').
  final String? specializationTags;
  const ExerciseCatalogData({
    this.syncUuid,
    this.updatedAt,
    this.syncedAt,
    this.deletedAt,
    required this.id,
    this.slug,
    required this.name,
    required this.primaryMuscle,
    required this.equipment,
    required this.mechanics,
    required this.force,
    required this.plane,
    required this.defaultRestSeconds,
    required this.isCustom,
    this.aka,
    required this.category,
    this.movementPattern,
    this.movementPatternRaw,
    required this.modality,
    required this.cnsScore,
    required this.recoveryImpact,
    required this.loggingMetric,
    required this.supportsWeightedBodyweight,
    this.attachments,
    required this.isReviewed,
    this.movementFamily,
    this.movementSlug,
    this.allowedEquipment,
    this.requiredEquipmentKeys,
    this.maxEffortEligibility,
    this.programmingDifficulty,
    this.programmingCommonness,
    this.allowedTrainingStyles,
    this.technicalEligibility,
    this.disciplines,
    this.prerequisiteSlugs,
    this.scalingGroup,
    this.scalingOrder,
    this.competitionAnchor,
    this.specializationTags,
  });
  @override
